def refs():
    return [{**s, "subject": "science", "locator": "細胞是基本單位、單細胞與多細胞生物、細胞—組織—器官—器官系統—個體層次、草履蟲／酵母菌與生物功能", "observedPattern": "公立學校公開生物試題常以層次排序、單／多細胞生物與草履蟲／酵母菌情境，要求區分細胞、組織、器官及個體功能；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-da-iv-2-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供細胞基本單位、單／多細胞、組成層次與功能分工的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "說『細胞是生物體的基本單位』，最適合的意思是什麼？", {"A": "細胞能進行維持生命所需的基本活動，生物體的功能可由細胞或細胞合作完成", "B": "所有生物都只由一個細胞組成", "C": "每個細胞都能獨立完成多細胞生物的全部功能", "D": "細胞只是一種放大觀察用的圖形"}, "基本單位指生命活動的組成與功能基礎，不代表所有生物只有一個細胞，也不代表每個人體細胞能獨立完成全身工作。", "把『基本』拆成組成、功能與層次三個面向，避免把它誤讀成數量。", ["確認題目談的是生物體的組成基礎。", "列出細胞可進行的基本生命活動。", "比較單細胞和多細胞生物的完成方式。", "排除所有生物只有一個細胞的錯誤外推。", "所以選 A。"], "easy"),
    make(2, "草履蟲只有一個細胞，卻能攝食、運動與繁殖。最合理的解釋是？", {"A": "同一個細胞內含有能協調多項生命活動的構造與功能", "B": "草履蟲其實由許多器官系統組成", "C": "單細胞生物不需要進行代謝", "D": "一個細胞就等於一個器官系統"}, "草履蟲是單細胞生物，一個細胞需完成個體的基本生活功能；不能因此把細胞和器官系統當成同義詞。", "先判斷個體由幾個細胞組成，再追蹤功能由哪個層次完成。", ["辨認草履蟲是一個單細胞個體。", "列出攝食、運動和繁殖等生命活動。", "說明這些功能由同一細胞內的不同構造協調。", "排除器官系統與細胞的層次混淆。", "所以選 A。"], "medium"),
    make(3, "人體的『細胞→組織→器官→器官系統→個體』階梯中，哪個例子配對最恰當？", {"A": "心肌細胞→心肌組織→心臟→循環系統→人體", "B": "心臟→心肌細胞→循環系統→組織→人體", "C": "循環系統→心臟→心肌組織→心肌細胞→人體", "D": "心肌組織→人體→心臟→循環系統→心肌細胞"}, "相似細胞形成組織，組織共同構成器官，多個器官合作成器官系統，最後形成個體；A 符合由小到大的組成順序。", "先確認每一項的層次，再依由小到大的組成關係排列。", ["辨認心肌細胞是單一細胞層次。", "確認心肌細胞群形成心肌組織。", "確認心肌組織與其他組織構成心臟。", "把心臟放入循環系統，再連到人體個體。", "所以選 A。"], "medium"),
    make(4, "下列哪一項最能說明多細胞生物需要細胞分工？", {"A": "肌肉細胞負責收縮，神經細胞傳遞訊息，兩者合作才能完成快速動作", "B": "人體每個細胞都能單獨消化食物、運送氧氣和感受刺激", "C": "多細胞生物所有細胞的形狀與功能都完全相同", "D": "細胞分工表示不同細胞不需要彼此協調"}, "多細胞生物的細胞會分化並各自擅長不同功能，仍需透過組織和系統協調完成整體活動。", "把構造／功能差異和合作關係同時放進解釋。", ["找出題目中的不同細胞類型。", "分別配對肌肉收縮與神經傳訊功能。", "說明單一功能不足以完成整體動作。", "補上兩類細胞需要互相協調的條件。", "所以選 A。"], "easy"),
    make(5, "酵母菌可用一個細胞完成代謝與出芽繁殖。這個例子支持哪項判斷？", {"A": "酵母菌通常可作為單細胞真菌，單一細胞能完成個體的基本生命活動", "B": "酵母菌一定是由器官系統組成的動物", "C": "只要能繁殖就一定是多細胞生物", "D": "真菌細胞不具有任何細胞構造"}, "酵母菌的個體通常由單一細胞構成，能在該細胞中完成代謝與繁殖；是否繁殖不是判斷多細胞的條件。", "分別檢查分類、細胞數量與功能完成位置，不被生活用途或名稱誤導。", ["確認酵母菌的生物分類。", "確認題目描述的是單一細胞個體。", "把代謝和出芽繁殖放回單一細胞的功能。", "排除把繁殖能力誤當成多細胞證據。", "所以選 A。"], "medium"),
    make(6, "某段文字寫『肌肉是一個細胞，心臟是許多肌肉放大後形成的細胞』。哪裡需要修正？", {"A": "肌肉通常是組織，心臟是由多種組織構成的器官，不能把器官當成單一放大細胞", "B": "肌肉一定是器官系統，心臟一定是單一細胞", "C": "組織和器官沒有層次差異", "D": "只要構造看起來大，就一定是器官系統"}, "肌肉組織由許多相似細胞構成；心臟還包含結締、神經等組織，是器官，不是單一巨大細胞。", "用組成成分反查層次名稱，不用外觀大小決定分類。", ["把肌肉拆成許多相似肌肉細胞。", "確認細胞群形成肌肉組織。", "檢查心臟是否含多種組織共同工作。", "因此把心臟分類為器官而非一顆大細胞。", "所以選 A。"], "medium"),
    make(7, "病毒缺乏完整細胞結構時，為何不能直接排入細胞—組織—器官的生物體層次？", {"A": "該層次描述以細胞為基本單位的生物體，病毒需依其非細胞性與寄生特性另行判讀", "B": "病毒只是最小的器官，所以不必有細胞", "C": "病毒一定比細胞大，因此不能分類", "D": "只要能造成疾病就一定是器官"}, "細胞—組織—器官階梯以細胞為基本單位；病毒沒有完整細胞結構，不能把它直接當成細胞或器官。", "先檢查分類架構的前提，再判斷例外對象是否符合。", ["確認該層次的起點是細胞。", "列出病毒缺乏完整細胞結構的條件。", "判斷它不符合一般細胞生物的組成階梯。", "另以非細胞性與寄生特性描述，而非硬套器官名稱。", "所以選 A。"], "hard"),
    make(8, "跑步時，肌肉、心臟與肺需要互相合作。最合理的層次解釋是？", {"A": "不同器官的細胞與組織分工，透過器官系統協調供氧、運輸與收縮", "B": "只有肌肉細胞工作，其他器官不參與", "C": "肺本身就是一個細胞，可以獨立運送血液", "D": "器官系統只是把所有細胞隨意堆在一起"}, "跑步需要肌肉收縮、肺部氣體交換與心血管運輸，跨器官系統協調才能供應能量與移動。", "從單一功能追到參與的器官，再確認它們如何由系統協調。", ["列出跑步需要的收縮、供氧和運輸功能。", "分別找出肌肉、肺與心臟的角色。", "把各器官放入相關器官系統。", "說明神經與循環等協調如何支援整體活動。", "所以選 A。"], "medium"),
    make(9, "下列哪種觀察最能支持『多細胞生物具有細胞分工』？", {"A": "同一個個體中，不同細胞具有不同形狀、構造與功能，且能在組織中合作", "B": "所有細胞大小完全相同且功能一樣", "C": "只看個體外表就能知道每一種細胞的功能", "D": "只要細胞數量多，就不需任何功能證據"}, "細胞分化與組織合作是多細胞分工的證據；數量多本身不足以說明細胞怎麼分工。", "同時檢查形態、構造、功能與合作證據，而不是只數細胞。", ["找出同一個體內的不同細胞類型。", "比較它們的形狀或構造差異。", "連結各自的功能與所在組織。", "確認功能間有合作而非只存在數量差。", "所以選 A。"], "easy"),
    make(10, "要判斷一個案例屬於單細胞或多細胞生物，最穩妥的作答順序是？", {"A": "先判定一個個體由幾個細胞構成，再看生活功能是否集中或由分工細胞合作完成", "B": "只看個體大小，越大就一定多細胞", "C": "只看能否移動，會移動就一定多細胞", "D": "只看名稱是否含『菌』或『蟲』"}, "單／多細胞的核心是個體的細胞數量與功能組織方式；外觀大小、移動和名稱都可能誤導。", "先做組成判斷，再用功能分工驗證，最後才引用例子。", ["確認題目中的『一個個體』範圍。", "判定它由一個或多個細胞組成。", "若是多細胞，再檢查是否有細胞分化與層次合作。", "排除以大小、移動或名稱直接分類。", "所以選 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
